//! Original BQ065: advancement X is the selected Shoggoth core's printed cost;
//! the optional extra shield is exactly one. Closed candidate, no new core rules.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
pub(crate) const ID:&str="BQ065";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn shield_options()->Vec<ChoiceOption>{vec![ChoiceOption{id:"shield".into(),label:"额外放置一个护盾".into(),card:None}]}
impl Game {
 pub(crate) fn plan_threshold(&self,c:&Card)->Option<u32>{if c.definition!=ID{return crate::batch4_plans::threshold(&c.definition);}self.core_zones.iter().find(|z|z.owner==c.controller&&catalog::card(&z.definition).subtitle.as_deref()==Some("修格斯")).map(|z|catalog::card(&z.definition).cost)}
 pub(crate) fn bq065_declare(&mut self,d:&Declaration)->RuleResult<()>{self.validate_plan_declaration(d)?;if self.players[d.actor].eliminated{return Ok(());}let options=self.binding_options(d.actor,&d.source,&d.ability.targets[0]);if options.is_empty(){return Err("修格斯计划没有可声明的地区".into());}self.choice(d.actor,"bq065-region","计划：修格斯达成推进：选择目标地区".into(),options,1,1,None,ChoiceResolution::Declare{declaration:d.clone(),stage:DeclareChoice::Target});Ok(())}
 pub(crate) fn bq065_complete(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_plan_frame(f)?;if f.source.card.definition!=ID||f.ability_key!=crate::batch4_plans::COMPLETE||f.cursor!=1{return Err("核心放置必须来自原计划完成程序".into());}let Some(t)=f.targets.first()else{return Err("核心放置缺原地区".into());};let Some(region)=t.id.strip_prefix("region:").and_then(|s|s.parse::<usize>().ok())else{return Err("核心放置目标不是地区".into());};if !self.region_live(region)||t.region_instance.as_deref()!=Some(self.regions[region].card.id.as_str()){return Ok(());}self.remove_dead(&f.source.card.id,RemovalCause::Sacrifice);
 let Some(index)=self.core_zones.iter().position(|z|z.owner==f.actor&&catalog::card(&z.definition).subtitle.as_deref()==Some("修格斯")&&z.card.is_some())else{return Ok(());};let c=self.core_zones[index].card.take().unwrap();let mut c=self.fresh(c);c.controller=f.actor;let id=c.id.clone();let definition=c.definition.clone();self.regions[region].cards.push(c);self.enter_triggers(f.actor,&definition,&id,false);
 if self.board(&id).is_some(){self.choice(f.actor,"bq065-shield","计划：修格斯：可以额外放置一个护盾".into(),shield_options(),0,1,None,ChoiceResolution::Frame{frame:Box::new(f.clone()),choice:FrameChoice::BQ065Shield{card_id:id}});}Ok(())}
 pub(crate) fn bq065_shield(&mut self,f:&ResolutionFrame,seat:usize,id:&str,selected:&[String])->RuleResult<()>{self.validate_plan_frame(f)?;if f.source.card.definition!=ID||f.ability_key!=crate::batch4_plans::COMPLETE||f.cursor!=1||seat!=f.actor||selected.len()>1||selected.first().is_some_and(|s|s!="shield"){return Err("额外护盾须由原完成帧选择一次".into());}if !selected.is_empty(){let c=self.board_mut(id).ok_or("原放置核心已离场")?;if c.owner!=seat||c.controller!=seat||c.face_down||!crate::core_zone::is_core(&c.definition){return Err("护盾只能给予原放置核心".into());}c.shield=c.shield.saturating_add(1);}Ok(())}
 pub(crate) fn bq065_cancelled_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if f.source.card.definition!=ID||f.ability_key!=crate::batch4_plans::COMPLETE||f.cursor!=0||!matches!(f.guard,GuardState::Cancelled)||!self.attachments.iter().any(|a|a.card.id==f.source.card.id&&a.card.controller==f.actor){return Err("计划失效收据须保留原在场计划".into());}let mut active=f.clone();active.guard=GuardState::Unchecked;self.validate_plan_frame(&active)}
 pub(crate) fn bq065_pending(&self,p:&Pending)->RuleResult<()>{let(actor,kind,title,min,options)=match &p.resolution{
 ChoiceResolution::Declare{declaration:d,stage}=>{self.validate_plan_declaration(d)?;if d.source.card.definition!=ID||!matches!(stage,DeclareChoice::Target){return Err("计划完成不能改成可选声明".into());}(d.actor,"bq065-region","计划：修格斯达成推进：选择目标地区",1,self.binding_options(d.actor,&d.source,&d.ability.targets[0]))},
 ChoiceResolution::Frame{frame:f,choice:FrameChoice::BQ065Shield{card_id}}=>{self.validate_plan_frame(f)?;if f.source.card.definition!=ID||f.ability_key!=crate::batch4_plans::COMPLETE||f.cursor!=1||self.batch3_physical_cards().any(|c|c.id==f.source.card.id)||self.board(card_id).is_none_or(|(_,c)|c.owner!=f.actor||c.controller!=f.actor||c.face_down||!crate::core_zone::is_core(&c.definition)||catalog::card(&c.definition).subtitle.as_deref()!=Some("修格斯"))||!self.mystic_instance_number(card_id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(c,f)|c>f){return Err("护盾续体缺原已放置核心及已牺牲计划".into());}(f.actor,"bq065-shield","计划：修格斯：可以额外放置一个护盾",0,shield_options())},_=>return Err("未知修格斯计划待选".into())};
 if p.seat!=actor||p.choice.player_id!=player_id(actor)||p.choice.kind!=kind||p.choice.title!=title||p.choice.min!=Some(min)||p.choice.max!=Some(1)||p.choice.allow_decline!=Some(min==0)||p.choice.description!="选择符合数量限制的选项，然后确认。"||p.choice.amount.is_some()||!p.choice.preview_cards.is_empty()||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice.options,&options){return Err("修格斯计划待选身份或选项损坏".into());}Ok(())}
}
